//! unsynn ships no Rust grammar: this is a minimal hand-written one, covering
//! only what the benchmark fixtures use (attributes, visibility, generics
//! without defaults, no where-clause, named/tuple/unit structs).

// Generated by `unsynn!`/`keyword!`.
#![allow(clippy::result_large_err)]

use unsynn::{
    BraceGroupContaining, BracketGroup, Colon, Comma, CommaDelimitedVec, Cons, Either, Except,
    Ident, LifetimeTick, ParenthesisGroup, ParenthesisGroupContaining, Parse as _, Pound,
    PunctAny, Semicolon, ToTokens, TokenStream, TokenTree, keyword, quote, unsynn,
};

type Input = proc_macro::TokenStream;

keyword! {
    KwStruct = "struct";
    KwPub = "pub";
    KwConst = "const";
}

type AnyLt = PunctAny<'<'>;
type AnyGt = PunctAny<'>'>;

unsynn! {
    struct Attribute {
        pound: Pound,
        body: BracketGroup,
    }

    struct Visibility {
        kw: KwPub,
        restriction: Option<ParenthesisGroup>,
    }

    /// One token tree, treating `<...>` as a nested unit.
    enum AngleTokenTree {
        Arrow(Cons<PunctAny<'-'>, AnyGt>),
        Nested(Cons<AnyLt, Vec<AngleTokenTree>, AnyGt>),
        Token(Cons<Except<Either<AnyLt, AnyGt>>, TokenTree>),
    }

    struct GenericParam {
        konst: Option<KwConst>,
        tick: Option<LifetimeTick>,
        name: Ident,
        bounds: Option<Cons<Colon, Vec<Cons<Except<Either<Comma, AnyGt>>, AngleTokenTree>>>>,
    }

    struct Generics {
        lt: AnyLt,
        params: CommaDelimitedVec<GenericParam>,
        gt: AnyGt,
    }

    struct NamedField {
        attrs: Vec<Attribute>,
        vis: Option<Visibility>,
        name: Ident,
        colon: Colon,
        ty: Vec<Cons<Except<Comma>, AngleTokenTree>>,
    }

    struct UnnamedField {
        attrs: Vec<Attribute>,
        vis: Option<Visibility>,
        ty: Vec<Cons<Except<Comma>, AngleTokenTree>>,
    }

    enum StructBody {
        Named(BraceGroupContaining<CommaDelimitedVec<NamedField>>),
        Unnamed(Cons<ParenthesisGroupContaining<CommaDelimitedVec<UnnamedField>>, Semicolon>),
        Unit(Semicolon),
    }

    struct DeriveStruct {
        attrs: Vec<Attribute>,
        vis: Option<Visibility>,
        kw: KwStruct,
        name: Ident,
        generics: Option<Generics>,
        body: StructBody,
    }
}

impl GenericParam {
    const fn is_type(&self) -> bool {
        self.konst.is_none() && self.tick.is_none()
    }

    /// The parameter as used in type position: `'a`, `T` or `N`.
    fn usage(&self) -> TokenStream {
        let tick = &self.tick;
        let name = &self.name;
        quote! { #tick #name }
    }
}

fn parse(input: Input) -> Result<DeriveStruct, Input> {
    let mut iter = TokenStream::from(input).into_token_iter();
    DeriveStruct::parse_all(&mut iter).map_err(|e| {
        let msg = e.to_string();
        quote! { compile_error!(#msg); }.into()
    })
}

/// `(impl_generics, ty_generics)`, adding `extra_bound` to every type parameter.
fn split_generics(generics: Option<&Generics>, extra_bound: &TokenStream) -> (TokenStream, TokenStream) {
    let Some(generics) = generics else {
        return (TokenStream::new(), TokenStream::new());
    };
    let params: Vec<_> = generics.params.iter().map(|d| &d.value).collect();
    let impl_params = params.iter().map(|p| {
        let bound = p.is_type().then_some(extra_bound).filter(|b| !b.is_empty());
        match (&p.bounds, bound) {
            (Some(_), Some(bound)) => quote! { #p + #bound, },
            (None, Some(bound)) => quote! { #p: #bound, },
            (_, None) => quote! { #p, },
        }
    });
    let ty_params = params.iter().map(|p| {
        let usage = p.usage();
        quote! { #usage, }
    });
    (quote! { < #{ impl_params } > }, quote! { < #{ ty_params } > })
}

#[cfg(feature = "small")]
pub fn named(input: Input) -> Input {
    let input = match parse(input) {
        Ok(input) => input,
        Err(e) => return e,
    };
    let (impl_generics, ty_generics) = split_generics(input.generics.as_ref(), &TokenStream::new());
    let name = &input.name;
    let name_str = name.to_string();
    quote! {
        impl #impl_generics #name #ty_generics {
            pub const NAME: &str = #name_str;
        }
    }
    .into()
}

#[cfg(feature = "big")]
pub fn heap_size(input: Input) -> Input {
    use unsynn::Literal;

    let input = match parse(input) {
        Ok(input) => input,
        Err(e) => return e,
    };
    let (impl_generics, ty_generics) =
        split_generics(input.generics.as_ref(), &quote! { crate::HeapSize });
    let name = &input.name;

    let sum = match &input.body {
        StructBody::Named(fields) => {
            let names = fields.content.iter().map(|f| &f.value.name);
            quote! { 0 #{ names.map(|n| quote! { + crate::HeapSize::heap_size_of_children(&self.#n) }) } }
        }
        StructBody::Unnamed(fields) => {
            let indices = (0..fields.first.content.len()).map(Literal::usize_unsuffixed);
            quote! { 0 #{ indices.map(|i| quote! { + crate::HeapSize::heap_size_of_children(&self.#i) }) } }
        }
        StructBody::Unit(_) => quote! { 0 },
    };

    quote! {
        impl #impl_generics crate::HeapSize for #name #ty_generics {
            fn heap_size_of_children(&self) -> usize {
                #sum
            }
        }
    }
    .into()
}
